  const dTxt = (J, o) => `distance ${f1(o.d)} against about ${J.dRef.toFixed(0)} for a window taken at random`;
  add('#obsBody .dj-it:not(.rp-it)', el => { const J = dj(); if (!J) return null; const j = +el.dataset.i, o = J.an[j], e = J.ends[j], c = cfg(); if (!o) return null; const hz = djDur(c.dvH * c.dvTf);
    return card({ title: `Match ${j + 1}: ${pretty(o.s)} · ${dts(o.t)} UTC`, chip: `the ${ordw(j)} shape of ${J.an.length}`, tone: '', value: `${keep(obsSgn(e, 1))} ${UN()}`, vcls: '', vlabel: `Move over the next ${hz}, rescaled to ${PR()}`, sub: dTxt(J, o), plain: `The last ${c.dvW} bars of ${esc(pretty(o.s))} up to ${dts(o.t)} UTC had the ${ordw(j)} shape to the last ${c.dvW} bars of ${esc(PR())}. Over the ${c.dvH} bars after it, it moved ${keep(obsSgn(e, 1))} ${UN()} once rescaled by bar volatility.`, secs: [sec('This match', tbl([row('Pair', esc(pretty(o.s))), row('Pattern ends', `${dts(o.t)} UTC`), row('Shape distance', `${f1(o.d)} (0 = identical)`), row('A random window', `about ${J.dRef.toFixed(0)}`), row('Next move', `${keep(obsSgn(e, 1))} ${UN()}`, true)]))], watch: 'One match is one case. Only the spread of all 12, checked by the verdict, says anything.', use: 'Click to draw it on the chart; ↗ opens it on the Trade chart.' }); });
